// Package toolchain provides utilities for managing generated code.
package toolchain

import (
	"bytes"
	"errors"
)

// GeneratedHeader is the exact comment that must appear at the start of
// every generated file produced by capp. The final LF byte is required.
const GeneratedHeader = "// Code generated by capp. DO NOT EDIT.\n"

// RegenFunc regenerates the content of a generated file. It returns the
// new content or an error.
type RegenFunc func() ([]byte, error)

// ErrM1469 is returned when a generated file drifts from its expected
// content or fails validation checks.
var ErrM1469 = errors.New("M1469: generated file drift")

// CheckGenerated validates that content matches a generated file contract.
// It returns ErrM1469 if content is nil or empty, if regen is nil, or if
// content does not start exactly with GeneratedHeader (no BOM or leading
// bytes allowed). If the early checks pass, regen is invoked to obtain
// the expected content; any error from regen or any mismatch with content
// also returns ErrM1469. content and returned bytes are never mutated.
func CheckGenerated(content []byte, regen RegenFunc) error {
	if regen == nil {
		return ErrM1469
	}
	if len(content) == 0 {
		return ErrM1469
	}
	if !bytes.HasPrefix(content, []byte(GeneratedHeader)) {
		return ErrM1469
	}
	expected, err := regen()
	if err != nil {
		return ErrM1469
	}
	if !bytes.Equal(content, expected) {
		return ErrM1469
	}
	return nil
}
